import json
n=30
g=[[1]*n for _ in range(n)]
rs=[1,9,16]; cs=[1,10,20]
colors=[[2,4,3],[3,6,9],[9,4,5]]
for i,r in enumerate(rs):
  for j,c in enumerate(cs):
    for y in range(r,r+6):
      for x in range(c,c+6): g[y][x]=8
    for y in (r+2,r+3):
      for x in (c+2,c+3): g[y][x]=colors[i][j]
# sequence connections, for consecutive colors coordinates found in board, adjacent cardinal
coords={v:(i,j) for i,row in enumerate(colors) for j,v in enumerate(row)}
seq=[2,4,3,9,5,4,6,3,9]
for a,b in zip(seq,seq[1:]):
  i,j=coords[a]; ii,jj=coords[b]
  r,c=rs[i],cs[j]
  if i==ii:
    # fill gap between panel rectangles along marker rows
    yrows=(r+2,r+3)
    if jj>j: xs=range(cs[j]+6,cs[jj])
    else: xs=range(cs[jj]+6,cs[j])
    for y in yrows:
      for x in xs: g[y][x]=a
  elif j==jj:
    xcols=(c+2,c+3)
    if ii>i: ys=range(rs[i]+6,rs[ii])
    else: ys=range(rs[ii]+6,rs[i])
    for y in ys:
      for x in xcols: g[y][x]=a
# restore sequence strip at row 28
for k,v in enumerate([2,4,3,9,5,4,6,3,9]): g[28][1+2*k]=v
print(json.dumps(g))
print('changes:',[(y,x,g[y][x]) for y in range(30) for x in range(30) if g[y][x] not in (1,8)][:100])

